<?php declare(strict_types=1); namespace Haerriz\AgenticCommerce\Model\Resolver;
use Haerriz\AgenticCommerce\Model\Order\OrderService; use Haerriz\AgenticCommerce\Model\GraphQl\CustomerContext; use Haerriz\AgenticCommerce\Model\Identity\IdentityResolver; use Magento\Framework\Exception\AuthorizationException; use Magento\Framework\Exception\LocalizedException; use Magento\Framework\GraphQl\Config\Element\Field; use Magento\Framework\GraphQl\Exception\GraphQlAuthorizationException; use Magento\Framework\GraphQl\Exception\GraphQlInputException; use Magento\Framework\GraphQl\Query\ResolverInterface; use Magento\Framework\GraphQl\Schema\Type\ResolveInfo;
class OrdersResolver implements ResolverInterface { public function __construct(private OrderService $service,private IdentityResolver $identityResolver,private CustomerContext $customerContext){} public function resolve(Field $field,$context,ResolveInfo $info,array $value=null,array $args=null){$identity=$this->customerContext->identityForTool($context, $args['client_id']??null, 'get_recent_orders');try{$r=$this->service->recent($identity,(int)($args['limit']??5));return $r['orders'];}catch(AuthorizationException $e){throw new GraphQlAuthorizationException(__($e->getMessage()));}catch(LocalizedException $e){throw new GraphQlInputException(__($e->getMessage()));}} }
